@dataclass(frozen=True, kw_only=True)
class Dossier:
    """What was checked, what was found and what was decided on a case. Evidence is summarized by what was measured and its result, never by an engine's raw output."""

    checks: list[Check]
    created_at: str
    current_state: str
    decisions: list[Decision]
    """Every decision taken on the case, oldest first."""
    documents: list[Document]
    """The documents and selfies of the case with the reviewers' decision about each, oldest first, as GET /v1/cases/{id}/documents lists them."""
    external_reference: str
    findings: list[Finding]
    id: str
    kind: Literal["KYC", "KYB", "AGE"]
    livemode: bool
    """False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production."""
    parties: list[DossierParty]
    relationships: list[Relationship]
    reviews: list[Review]
    status: Literal["open", "processing", "awaiting_input", "in_review", "approved", "rejected", "cancelled", "expired"]
    status_market: Literal["PROCESSING", "PENDING_OCR", "PENDING", "APPROVED", "REPROVED", "BLOCKED", "CANCELLED", "EXPIRED"]
    """The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision."""
    updated_at: str
    workflow: DossierWorkflow | None
    """The workflow run and its steps, or null before the case starts."""

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Dossier:
        return cls(
            checks=[Check.from_dict(item) for item in data["checks"]],
            created_at=data["created_at"],
            current_state=data["current_state"],
            decisions=[Decision.from_dict(item) for item in data["decisions"]],
            documents=[Document.from_dict(item) for item in data["documents"]],
            external_reference=data["external_reference"],
            findings=[Finding.from_dict(item) for item in data["findings"]],
            id=data["id"],
            kind=data["kind"],
            livemode=data["livemode"],
            parties=[DossierParty.from_dict(item) for item in data["parties"]],
            relationships=[Relationship.from_dict(item) for item in data["relationships"]],
            reviews=[Review.from_dict(item) for item in data["reviews"]],
            status=data["status"],
            status_market=data["status_market"],
            updated_at=data["updated_at"],
            workflow=None if data.get("workflow") is None else DossierWorkflow.from_dict(data["workflow"]),
        )


