@dataclass(frozen=True, kw_only=True)
class PartyProfile:
    """PartyProfile is an object of KUAA's API."""

    cases: list[PartyProfileCase] | None
    """The cases it takes part in, newest first. Null for a key without case.list."""
    cnpj: str | None
    """The CNPJ of a BUSINESS as text, which may be alphanumeric. In full for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *."""
    cpf: str | None
    """The CPF of a PERSON as text. In full (11 digits) for a key with party.pii.view; otherwise masked, every character but the two check digits replaced by *."""
    id: str
    """The profile: the id of the first party row of this CPF or CNPJ in the organization. GET /v1/parties/{id} takes it, or any party id of the same person or company."""
    identity: Identity | None
    """What KUAA verified about the identifier across cases. Null when nothing was, or for a key without identity.view."""
    kind: Literal["PERSON", "BUSINESS"]
    livemode: bool
    """False when the answer comes from the organization's sandbox: synthetic data, engine doubles chosen by the documented magic values, nothing billed and no official source consulted. True in production."""
    monitoring: Monitoring
    name: str | None
    """The full name of a person or the razão social of a company, from its newest party row. Null without party.pii.view."""
    party_ids: list[str]
    """Every party row of this CPF or CNPJ in the organization, oldest first."""
    screenings: list[Screening] | None
    """The latest screening of each list among its party rows. Null for a key without evidence.view."""
    tags: list[PartyProfileTag] | None
    """The tags its party rows carry, without repeats. Null for a key without tag.list."""

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> PartyProfile:
        return cls(
            cases=None if data.get("cases") is None else [PartyProfileCase.from_dict(item) for item in data["cases"]],
            cnpj=data.get("cnpj"),
            cpf=data.get("cpf"),
            id=data["id"],
            identity=None if data.get("identity") is None else Identity.from_dict(data["identity"]),
            kind=data["kind"],
            livemode=data["livemode"],
            monitoring=Monitoring.from_dict(data["monitoring"]),
            name=data.get("name"),
            party_ids=data["party_ids"],
            screenings=None if data.get("screenings") is None else [Screening.from_dict(item) for item in data["screenings"]],
            tags=None if data.get("tags") is None else [PartyProfileTag.from_dict(item) for item in data["tags"]],
        )


@dataclass(frozen=True, kw_only=True)
class PartyProfileCase:
    """PartyProfileCase is an object of KUAA's API."""

    case_id: str
    created_at: str
    external_reference: str
    kind: Literal["KYC", "KYB", "AGE"]
    party_id: str
    """The party row of this person or company in the case."""
    primary: bool
    """Whether the case is about this person or company."""
    status: Literal["open", "processing", "awaiting_input", "in_review", "approved", "rejected", "cancelled", "expired"]
    status_market: Literal["PROCESSING", "PENDING_OCR", "PENDING", "APPROVED", "REPROVED", "BLOCKED", "CANCELLED", "EXPIRED"]
    """The status in the vocabulary of the Brazilian KYC market, beside status, which keeps its values: PROCESSING (open, processing, awaiting_input), PENDING_OCR (in_review because a document reading check -- OCR or validation -- failed or timed out), PENDING (in_review, waiting for a human decision), APPROVED (approved), REPROVED (rejected), BLOCKED (rejected by the policy's block outcome, such as a confirmed sanctions match), CANCELLED (cancelled) and EXPIRED (expired). CANCELLED and EXPIRED are closed without a decision. It never changes the decision."""

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> PartyProfileCase:
        return cls(
            case_id=data["case_id"],
            created_at=data["created_at"],
            external_reference=data["external_reference"],
            kind=data["kind"],
            party_id=data["party_id"],
            primary=data["primary"],
            status=data["status"],
            status_market=data["status_market"],
        )


