    share_percent: NotRequired[float]
    """The stake held, more than 0 and at most 100. Only for a shareholding."""
    to_party_id: NotRequired[str]
    """Reads "the new party is <role> of to_party_id". Give this or from_party_id, not both."""
    valid_from: NotRequired[str]
    """The first day the relationship holds, as YYYY-MM-DD."""
    valid_to: NotRequired[str]
