class CaptureForm(TypedDict):
    """CaptureForm is a multipart body of KUAA's API."""

    captured_at: NotRequired[list[str]]
    """Optional: when each file was captured, RFC 3339, one per file in the order of the files."""
    document_type: NotRequired[Literal["CIN", "RG", "CNH", "PASSPORT", "ADDRESS_PROOF", "CNPJ_CARD", "CCMEI", "ARTICLES", "AMENDMENT", "POWER_OF_ATTORNEY"]]
    """Required for a document, refused for anything else."""
    file: list[KuaaFile]
    """The images, JPEG or PNG, each at most 8 MiB, at least 64 pixels on a side and at most 25 megapixels: up to 2 for a document, 1 for a selfie, up to 32 frames for a liveness capture, in capture order."""
